<script setup lang="ts">
import { exportCsv } from '~/lib/exportCsv'
const year = ref(new Date().getFullYear()), data = ref<any>(null), form = ref<any>({})
const basis = ref('')
const loading = ref(true), loadError = ref(''), saving = ref(false)
const bhpRate = ref(0.5), usoRate = ref(1.25)
let request = 0
async function load() {
  const id = ++request; loading.value = true; loadError.value = ''
  try { const d = await api(`/api/bhp-uso?year=${year.value}${basis.value ? `&basis=${basis.value}` : ''}`); if (id === request) { data.value = d; basis.value = d.config.basis; form.value = { ...d.config }; bhpRate.value = d.config.bhp_rate / 100; usoRate.value = d.config.uso_rate / 100 } }
  catch (e) { if (id === request) loadError.value = errMsg(e) } finally { if (id === request) loading.value = false }
}
onMounted(load)
const base = computed(() => Number(data.value?.gross || 0) + Number(form.value.adjustment || 0) - Number(form.value.bad_debt || 0) - Number(form.value.interconnect || 0))
const bhp = computed(() => Math.round(Math.max(0, base.value) * bhpRate.value / 100))
const uso = computed(() => Math.round(Math.max(0, base.value) * usoRate.value / 100))
const dirty = computed(() => !!data.value && JSON.stringify({ ...form.value, bhp_rate: Math.round(bhpRate.value * 100), uso_rate: Math.round(usoRate.value * 100) }) !== JSON.stringify({ ...data.value.config, basis: data.value.saved_basis }))
const monthRows = computed(() => (data.value?.months || []).map((value: number, index: number) => ({ label: new Date(data.value.config.year, index, 1).toLocaleDateString('id-ID', { month: 'long' }), value })))
const pages = usePagination(monthRows, { resetOn: year })
const partnerPages = usePagination(() => data.value?.partners || [])
const selectedPartner = ref<any>(null)
const billPages = usePagination(() => (data.value?.bills || []).filter((b: any) => selectedPartner.value && b.partner_id === selectedPartner.value.id), { resetOn: selectedPartner })
const basisLabel = computed(() => data.value?.config.basis === 'paid' ? 'Pembayaran diterima (tanggal bayar)' : 'Total tagihan (periode layanan)')
const legacyCount = computed(() => (data.value?.partners || []).reduce((n: number, p: any) => n + p.legacy, 0))
async function save() {
  saving.value = true
  try { await api('/api/bhp-uso', { method: 'PUT', body: { ...form.value, bhp_rate: Math.round(bhpRate.value * 100), uso_rate: Math.round(usoRate.value * 100) } }); toast('Parameter perhitungan disimpan'); await load() }
  catch (e) { toast(errMsg(e), 'error') } finally { saving.value = false }
}
function download() {
  exportCsv(`estimasi-bhp-uso-${data.value.config.year}.csv`, [
    ['ESTIMASI INTERNAL BHP PENYELENGGARAAN TELEKOMUNIKASI & KPU/USO'], ['Tahun', data.value.config.year], ['Sumber', 'Tagihan pelanggan per mitra'], ['Basis', basisLabel.value], ['Status parameter', dirty.value ? 'Belum disimpan' : 'Tersimpan'],
    ['Pendapatan mitra', data.value.gross], ['Penyesuaian pendapatan', form.value.adjustment], ['Piutang nyata tidak tertagih', form.value.bad_debt], ['Interkoneksi / ketersambungan yang memenuhi syarat', form.value.interconnect], ['Dasar perhitungan', base.value], ['BHP %', bhpRate.value], ['Estimasi BHP', bhp.value], ['USO %', usoRate.value], ['Estimasi USO', uso.value], ['Total estimasi', bhp.value + uso.value], ['Jatuh tempo tahunan', data.value.due], ['Catatan', form.value.notes], ['Referensi bukti', form.value.evidence], [], ['Bulan', 'Pendapatan telekomunikasi'], ...monthRows.value.map((m: any) => [m.label, m.value]), [], ['Mitra', 'Jumlah tagihan', 'Pendapatan'], ...data.value.partners.map((p: any) => [p.name, p.bills, p.gross]), [], ['ID tagihan', 'Mitra', 'Pelanggan', 'Periode', 'Tanggal sumber', 'Jumlah', 'Status'], ...data.value.bills.map((b: any) => [b.id,b.partner,b.customer,b.period,b.date,b.amount,b.status])
  ])
}
</script>
<template>
  <div class="card op-hero"><div><span class="op-eyebrow">Kewajiban telekomunikasi</span><h2>Siapkan BHP & KPU/USO.</h2><p>Estimasi dari pendapatan pelanggan pada setiap mitra. Telusuri nilai sumber, bulan, dan tagihannya.</p></div><NuxtLink class="btn btn-sec" to="/pembukuan">Buka pembukuan</NuxtLink></div>
  <form class="op-filters" @submit.prevent="load"><label>Tahun perhitungan<input v-model.number="year" @change="basis = ''" class="ctrl" type="number" min="2000" max="2100" required /></label><label>Sumber pendapatan<select v-model="basis" class="ctrl"><option value="">Sesuai parameter tahun</option><option value="billed">Total tagihan mitra</option><option value="paid">Pembayaran diterima dari mitra</option></select></label><button class="btn btn-sec" :disabled="loading">Tampilkan</button></form>
  <div v-if="loading" class="empty">Memuat perhitungan…</div><div v-else-if="loadError" class="op-note op-warning" role="alert">{{ loadError }}</div>
  <template v-else-if="data">
    <div class="op-note"><strong>{{ basisLabel }}</strong>{{ data.config.basis === 'paid' ? 'Hanya tagihan lunas dengan tanggal pembayaran pada tahun ini. Pembayaran tagihan tahun sebelumnya ikut pada tahun saat diterima.' : 'Seluruh tagihan pada periode tahun ini, termasuk yang belum lunas.' }} Nilai sebelum bagi hasil. FAB merupakan rekap sehingga tidak dihitung kembali.</div>
    <div v-if="data.warning" class="op-note op-warning">{{ data.warning }}</div>
    <div v-if="data.partners.some((p: any) => p.id === 0)" class="op-note op-warning">Ada pendapatan tanpa mitra. Nilainya tetap disertakan agar total tidak berkurang; periksa rincian sumber.</div>
    <div class="op-metrics"><div class="card op-metric"><span>Pendapatan mitra</span><strong>{{ fmtRp(data.gross) }}</strong><small>{{ data.bills.length }} tagihan · {{ data.config.year }}</small></div><div class="card op-metric"><span>Estimasi BHP · {{ bhpRate }}%</span><strong>{{ base < 0 ? 'Periksa dasar' : fmtRp(bhp) }}</strong><small>Penyelenggaraan telekomunikasi</small></div><div class="card op-metric"><span>Estimasi USO · {{ usoRate }}%</span><strong>{{ base < 0 ? 'Periksa dasar' : fmtRp(uso) }}</strong><small>Kontribusi pelayanan universal</small></div><div class="card op-metric"><span>Total estimasi</span><strong>{{ base < 0 ? 'Periksa dasar' : fmtRp(bhp + uso) }}</strong><small>Jatuh tempo {{ data.due }}</small></div></div>
    <div class="card" style="margin-bottom:22px"><div class="op-panel-head"><h3>Pendapatan per mitra</h3><span class="cell-sub">{{ basisLabel }}</span></div><div class="table-wrap"><table class="tbl"><thead><tr><th>Mitra</th><th class="num">Tagihan</th><th class="num">Pendapatan</th><th>Rincian</th></tr></thead><tbody><tr v-for="p in partnerPages.rows" :key="p.id"><td class="cell-main">{{ p.name }}</td><td class="num">{{ p.bills }}</td><td class="num">{{ fmtRp(p.gross) }}</td><td><button class="btn btn-sec btn-sm" @click="selectedPartner = p">Lihat tagihan</button></td></tr><tr v-if="!partnerPages.total"><td colspan="4" class="empty">Belum ada pendapatan mitra untuk tahun dan basis ini.</td></tr></tbody></table></div><TablePagination v-model:page="partnerPages.page" v-model:page-size="partnerPages.pageSize" :total="partnerPages.total" label="pendapatan mitra" /><p v-if="legacyCount" class="hint" style="padding:0 22px 16px">{{ legacyCount }} tagihan lama memakai mitra saat migrasi fitur. Tagihan baru menyimpan mitra saat diterbitkan agar perubahan pelanggan tidak mengubah sumber historis.</p></div>
    <div class="op-split">
      <div class="card"><div class="op-panel-head"><h3>Dasar & parameter perhitungan</h3><span class="op-status" :class="{ off: dirty }">{{ dirty ? 'Belum disimpan' : 'Parameter tersimpan / bawaan' }}</span></div><form class="op-body" @submit.prevent="save"><div class="grid-form"><div class="field"><label for="rate-bhp">Tarif BHP (%)</label><input id="rate-bhp" v-model.number="bhpRate" class="ctrl" type="number" min="0" max="100" step="0.01" required /></div><div class="field"><label for="rate-uso">Tarif USO (%)</label><input id="rate-uso" v-model.number="usoRate" class="ctrl" type="number" min="0" max="100" step="0.01" required /></div><div class="field full"><label for="levy-adjustment">Penyesuaian pendapatan (Rp, boleh negatif)</label><input id="levy-adjustment" v-model.number="form.adjustment" class="ctrl" type="number" min="-1000000000000" max="1000000000000" step="1" required /><span class="hint">Contoh: pendapatan yang belum tercakup pada tagihan mitra. Sertakan alasan dan rujukan.</span></div><div class="field full"><label for="levy-debt">Piutang nyata tidak tertagih yang memenuhi syarat (Rp)</label><input id="levy-debt" v-model.number="form.bad_debt" class="ctrl" type="number" min="0" max="1000000000000" step="1" required /></div><div class="field full"><label for="levy-interconnect">Kewajiban interkoneksi / ketersambungan yang memenuhi syarat (Rp)</label><input id="levy-interconnect" v-model.number="form.interconnect" class="ctrl" type="number" min="0" max="1000000000000" step="1" required /><span class="hint">Bagian yang diterima dan menjadi hak penyelenggara lain. Tidak semua biaya bandwidth atau bagi hasil otomatis memenuhi syarat.</span></div><div class="field full"><label for="levy-evidence">Referensi bukti pengurang</label><textarea id="levy-evidence" v-model="form.evidence" class="ctrl" rows="2" maxlength="2000" :required="form.bad_debt > 0 || form.interconnect > 0" placeholder="Nomor dokumen, periode, dan lokasi penyimpanan bukti"></textarea></div><div class="field full"><label for="levy-notes">Alasan penyesuaian / perubahan tarif</label><textarea id="levy-notes" v-model="form.notes" class="ctrl" rows="3" maxlength="2000" :required="form.adjustment !== 0 || bhpRate !== 0.5 || usoRate !== 1.25"></textarea></div></div><div class="op-note" :class="{ 'op-warning': base < 0 }"><strong>Dasar hitung: {{ fmtRp(base) }}</strong>Pendapatan + penyesuaian − piutang memenuhi syarat − interkoneksi memenuhi syarat. Pembulatan estimasi ke rupiah terdekat.</div><div class="op-actions"><button class="btn btn-primary" :disabled="saving || base < 0">{{ saving ? 'Menyimpan…' : 'Simpan parameter' }}</button><button type="button" class="btn btn-sec" :disabled="base < 0" @click="download">Ekspor perhitungan</button></div></form></div>
      <div class="op-stack"><div class="card"><div class="op-panel-head"><h3>Pendapatan per bulan</h3><span class="cell-sub">{{ data.config.year }}</span></div><div class="table-wrap"><table class="tbl"><thead><tr><th>Bulan</th><th class="num">Pendapatan</th></tr></thead><tbody><tr v-for="m in pages.rows" :key="m.label"><td>{{ m.label }}</td><td class="num">{{ fmtRp(m.value) }}</td></tr></tbody></table></div><TablePagination v-model:page="pages.page" v-model:page-size="pages.pageSize" :total="pages.total" label="pendapatan bulanan BHP USO" /><div class="op-total"><span>Total tercatat</span><span>{{ fmtRp(data.gross) }}</span></div></div><div class="card op-body"><span class="op-eyebrow">Cara membaca hasil</span><p class="op-text">Sumber pendapatan langsung dari nilai tagihan tersimpan per mitra. Perhitungan ini tidak membutuhkan saldo awal atau sinkronisasi jurnal. Bagi hasil mitra tidak dikurangkan otomatis.</p><p class="op-text">Hasil ini untuk perencanaan internal. Menyimpan parameter tidak membuat jurnal, melaporkan kewajiban, atau melakukan pembayaran. Gunakan jurnal pencadangan dan pembayaran di Pembukuan sesuai bukti.</p><p class="op-text">Tarif bawaan BHP 0,50% dan USO 1,25%; batas bayar tahunan 30 April tahun berikutnya. Modul ini tidak menghitung BHP frekuensi radio.</p><p class="op-text">Rujukan: <a class="op-link" href="https://jdih.komdigi.go.id/produk_hukum/view/id/768/t/peraturan%2Bmenteri%2Bkomunikasi%2Bdan%2Binformatika%2Bnomor%2B5%2Btahun%2B2021" target="_blank" rel="noopener">Permenkominfo 5/2021</a> dan <a class="op-link" href="https://peraturan.go.id/files/pp-no-43-tahun-2023.pdf" target="_blank" rel="noopener">PP 43/2023</a>. Pengurang perlu diperiksa berdasarkan bukti dan ketentuan yang berlaku.</p></div></div>
    </div>
  </template>
  <UiModal :open="!!selectedPartner" :title="`Sumber pendapatan · ${selectedPartner?.name || ''}`" wide @close="selectedPartner = null"><p class="op-text">{{ basisLabel }} · {{ data?.config.year }}</p><div class="table-wrap"><table class="tbl"><thead><tr><th>Tagihan / pelanggan</th><th>Periode</th><th>Tanggal sumber</th><th>Status</th><th class="num">Jumlah</th></tr></thead><tbody><tr v-for="b in billPages.rows" :key="b.id"><td>#{{ b.id }} · {{ b.customer }}</td><td>{{ b.period }}</td><td>{{ b.date }}</td><td>{{ b.status }}</td><td class="num">{{ fmtRp(b.amount) }}</td></tr></tbody></table></div><TablePagination v-model:page="billPages.page" v-model:page-size="billPages.pageSize" :total="billPages.total" label="tagihan sumber BHP USO" /></UiModal>
</template>
